<script setup lang="ts">
import { computed, ref } from 'vue'
import type { EChartsOption } from 'echarts'
import type { Json, SampleData } from '../types'
import { navigate, notify } from '../state'
import Icon from '../components/Icon.vue'
import ChartPanel from '../components/ChartPanel.vue'
const props = defineProps<{ data: SampleData }>()
const clickedDate = ref(''), clickedMetric = ref('')
const mode = ref('production'), period = ref('all'), detail = ref(false)
const sourceRows = computed(() => props.data.analytics.cost?.rows || [])
const rows = computed(() => sourceRows.value.filter(r => period.value === 'all' || String(r.statDate) === period.value))
const money = (v: number) => v.toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
const sum = (key: string) => rows.value.reduce((n, r) => n + (typeof r[key] === 'number' ? r[key] as number : 0), 0)
const metrics = computed(() => ({ total: sum('totalCost'), material: sum('totalMaterialCost'), labor: sum('totalLaborCost'), batches: sum('batchCount') }))
const dates = computed(() => [{ label: '已收录统计区间', value: 'all' }, ...sourceRows.value.map(r => ({ label: String(r.statDate), value: String(r.statDate) }))])
const common = { textStyle: { fontFamily: 'Segoe UI, Microsoft YaHei, sans-serif', color: '#8290a2' }, tooltip: { trigger: 'axis' as const, backgroundColor: '#fff', borderColor: '#e5eaf0', textStyle: { color: '#26374d', fontSize: 12 } }, grid: { top: 24, left: 12, right: 20, bottom: 12, containLabel: true } }
const costOption = computed<EChartsOption>(() => ({ ...common, color: ['#1b65a8', '#6ca5d7', '#a7c6df', '#d6e2ed'], legend: { bottom: 0, itemWidth: 8, itemHeight: 8, icon: 'circle', textStyle: { color: '#718096', fontSize: 11 } }, grid: { ...common.grid, bottom: 44 }, xAxis: { type: 'category', data: rows.value.map(r => String(r.statDate).slice(5)), axisLine: { show: false }, axisTick: { show: false } }, yAxis: { type: 'value', axisLabel: { formatter: (v: number) => v >= 1000 ? (v / 1000) + 'k' : String(v) }, splitLine: { lineStyle: { color: '#eef2f6', type: 'dashed' } } }, series: [['物料', 'totalMaterialCost'], ['人工', 'totalLaborCost'], ['设备', 'totalEquipmentCost'], ['其他', 'totalOtherCost']].map(([name, key]) => ({ name, type: 'bar', stack: 'cost', barMaxWidth: 55, data: rows.value.map(r => typeof r[key] === 'number' ? r[key] as number : null), itemStyle: { borderRadius: name === '人工' ? [4, 4, 0, 0] : 0 } })) }))
const donutOption = computed<EChartsOption>(() => ({ ...common, tooltip: { trigger: 'item', formatter: '{b}<br/>¥{c} · {d}%' }, color: ['#1b65a8', '#79aad4', '#acbfce', '#dde5ed'], graphic: [{ type: 'text', left: 'center', top: '39%', style: { text: metrics.value.batches + ' 批', fill: '#24374e', font: '600 27px Segoe UI' } }, { type: 'text', left: 'center', top: '53%', style: { text: '报表覆盖', fill: '#92a0b1', font: '12px Microsoft YaHei' } }], series: [{ type: 'pie', radius: ['65%', '82%'], center: ['50%', '48%'], avoidLabelOverlap: true, label: { show: false }, itemStyle: { borderRadius: 3, borderColor: '#fff', borderWidth: 3 }, data: [{ name: '物料', value: metrics.value.material }, { name: '人工', value: metrics.value.labor }, { name: '设备', value: sum('totalEquipmentCost') }, { name: '其他', value: sum('totalOtherCost') }] }] }))
const statuses = computed(() => Object.entries(props.data.plans.reduce<Record<string, number>>((acc, p) => { const key = p.statusDisplayName || p.status; acc[key] = (acc[key] || 0) + 1; return acc }, {})))
const planOption = computed<EChartsOption>(() => ({ ...common, color: ['#4389bd'], grid: { top: 8, left: 10, right: 28, bottom: 0, containLabel: true }, xAxis: { type: 'value', minInterval: 1, splitLine: { lineStyle: { color: '#f0f3f7', type: 'dashed' } } }, yAxis: { type: 'category', data: statuses.value.map(([s]) => s), axisTick: { show: false }, axisLine: { show: false } }, series: [{ type: 'bar', barWidth: 17, data: statuses.value.map(([, n]) => n), label: { show: true, position: 'right', color: '#64748b' }, itemStyle: { borderRadius: [0, 4, 4, 0] } }] }))
const units = computed(() => Object.entries(props.data.plans.reduce<Record<string, { count: number; quantity: number }>>((acc, p) => { const key = p.plannedUnit || '未提供单位'; acc[key] ||= { count: 0, quantity: 0 }; acc[key].count++; if (p.plannedQuantity != null) acc[key].quantity += p.plannedQuantity; return acc }, {})))
function showCostPoint(point: {dataIndex: number; seriesName: string}) { clickedDate.value = String(rows.value[point.dataIndex]?.statDate || ''); clickedMetric.value = point.seriesName; detail.value = true }
const detailRows = computed(() => rows.value.filter(r => !clickedDate.value || String(r.statDate) === clickedDate.value))
function download() { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify({ scope: 'F006账号快照', selectedPeriod: period.value, rows: rows.value, sources: props.data.analytics.sourceKeys }, null, 2)], { type: 'application/json' })); a.download = 'F006-成本报表-快照.json'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); notify('已导出当前统计范围及其数据来源。') }
const insight = computed(() => metrics.value.total ? `已收录成本报表覆盖 ${metrics.value.batches} 个批次，物料成本占比 ${(metrics.value.material / metrics.value.total * 100).toFixed(1)}%。这是报表所含记录的合计，不能据此断言全厂本月成本或经营利润。` : '当前筛选范围没有可汇总的成本记录，调整范围后重试。')
const rawValue = (v: Json) => v === null ? '—（源记录未提供）' : typeof v === 'object' ? JSON.stringify(v) : String(v)
</script>

<template>
  <div class="page-head"><div><div class="eyebrow">生产与经营 / 数据分析</div><h1>数据分析</h1><p>先看清当前生产成本，再分析经营、上传数据和业务趋势。</p></div><div class="head-actions"><USelect v-model="period" :items="dates" aria-label="选择分析日期" /><UButton color="neutral" variant="outline" @click="download"><Icon name="file" :size="16" />导出数据</UButton></div></div>
  <div class="fusion-cost-section">
    <div class="analysis-metrics"><div><span>记录成本合计</span><strong><small>¥</small>{{ money(metrics.total) }}</strong><p>所选源成本报表行合计</p></div><div><span>物料成本</span><strong><small>¥</small>{{ money(metrics.material) }}</strong><p>来源：报表物料成本项</p></div><div><span>人工成本</span><strong><small>¥</small>{{ money(metrics.labor) }}</strong><p>来源：报表人工成本项</p></div><div><span>报表覆盖批次</span><strong>{{ metrics.batches }}<small>批</small></strong><p>另有 {{ data.batches.length }} 条批次快照，不混为同一口径</p></div></div>
    <div class="analysis-grid"><section class="surface cost-trend"><div class="panel-heading"><div><h3>成本构成趋势</h3><p>按源统计日 · 元</p></div><button class="text-button" @click="clickedDate = ''; clickedMetric = ''; detail = true">查看明细 <Icon name="arrow" :size="15" /></button></div><ChartPanel @select="showCostPoint" :option="costOption" :height="295" label="源成本报表各日期的物料、人工、设备和其他成本" /><div class="chart-footnote">缺失项保留为空，不把未提供的成本自动改成 0。</div></section><section class="surface cost-composition"><div class="panel-heading"><div><h3>成本占比</h3><p>仅含所选记录</p></div><button class="icon-button" aria-label="查看成本占比明细" @click="clickedDate = ''; detail = true"><Icon name="more" :size="18" /></button></div><ChartPanel @select="clickedDate = ''; clickedMetric = $event.name; detail = true" :option="donutOption" :height="222" label="源成本记录的物料与人工成本比例" /><div class="legend-lines"><span><i class="dot blue" />物料<b>¥{{ money(metrics.material) }}</b></span><span><i class="dot pale-blue" />人工<b>¥{{ money(metrics.labor) }}</b></span></div></section></div>
    <section class="insight-band"><span class="insight-icon"><Icon name="ai" :size="23" /></span><div><h3>这组数据告诉我们什么</h3><p>{{ insight }}</p><small>本地口径说明 · 由当前快照计算，不是实时模型结论</small></div><UButton color="neutral" variant="outline" @click="navigate('ai')">继续向助手提问<Icon name="arrow" :size="15" /></UButton></section>
    <div class="analysis-grid bottom-analysis"><section class="surface"><div class="panel-heading"><div><h3>生产计划状态</h3><p>{{ data.plans.length }} 张计划 · 按状态计数</p></div><button class="text-button" @click="navigate('plans')">查看计划<Icon name="arrow" :size="15" /></button></div><ChartPanel @select="navigate('plans')" :option="planOption" :height="205" label="当前账号各状态生产计划数量" /></section><section class="surface"><div class="panel-heading"><div><h3>计划数量 · 按单位分组</h3><p>不同单位分开呈现，避免错误相加</p></div><Icon name="layers" /></div><div class="unit-summary" v-for="[unit, value] in units" :key="unit"><span class="unit-square">{{ unit }}</span><div><strong>{{ value.quantity.toLocaleString('zh-CN', { maximumFractionDigits: 3 }) }} <small>{{ unit }}</small></strong><span>{{ value.count }} 张计划</span></div><span class="status-badge gray">独立口径</span></div></section></div>
  </div>
  <UModal v-model:open="detail" title="成本统计原始记录" description="当前筛选范围的源报表字段，可对照核验" :ui="{ content: 'max-w-3xl' }"><template #body><p v-if="clickedMetric" class="chart-selection-note">当前关注：{{ clickedMetric }}{{ clickedDate ? ' · ' + clickedDate : '' }} · 以下保留完整统计行</p><div v-for="(row, index) in detailRows" :key="index" class="raw-record"><h3>{{ row.statDate }}</h3><div class="raw-fields"><div v-for="(v, k) in row" :key="k"><span>{{ k }}</span><code>{{ rawValue(v) }}</code></div></div></div><div class="source-note"><Icon name="book" /><div v-for="key in data.analytics.sourceKeys" :key="key"><small>{{ key }}</small></div></div></template></UModal>
</template>
